#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long INF = 2e18;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> t(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> t[i];
    }

    // Ordena em ordem decrescente (1-indexed)
    sort(t.begin() + 1, t.end(), greater<long long>());

    // dp_prev[i] armazena o menor custo para formar (j - 1) trios usando um subconjunto de t[1...i]
    // dp_curr[i] armazenará o menor custo para formar j trios
    vector<long long> dp_prev(n + 1, 0);
    vector<long long> dp_curr(n + 1, INF);

    for (int j = 1; j <= k; ++j) {
        fill(dp_curr.begin(), dp_curr.end(), INF);
        for (int i = 3 * j; i <= n; ++i) {
            long long diff = t[i - 1] - t[i];
            long long cost = diff * diff;
            dp_curr[i] = min(dp_curr[i - 1], dp_prev[i - 2] + cost);
        }
        dp_prev = dp_curr;
    }

    cout << dp_curr[n] << "\n";

    return 0;
}
